 nav=dict(use_sim_time=True,global_frame='map',robot_base_frame='base_link',odom_topic='/s05/odometry',bt_loop_duration=20,default_server_timeout=1000,wait_for_service_timeout=2000,default_nav_to_pose_bt_xml=str(PKG/'config/navigate.xml'),navigators=['navigate_to_pose'],navigate_to_pose=dict(plugin='nav2_bt_navigator::NavigateToPoseNavigator'),transform_tolerance=.15,filter_duration=.3)
